    "required": [
        "username",
        "password"
    ],
    "properties": {
        "credentials": {
            "type": "object",
            "username": {
                "description": "The persons unique id in the system",
                "$ref": "#/definitions/login"
            },
            "password": {
                "description": "The persons unique id in the system",
                "$ref": "#/definitions/login"
            },
            "api": {
                "type": "object",
                "properties": {
                    "key": {
                        "oneOf": [
                            {
                                "$ref": "#/definitions/nested"
                            },
                            {
                                "type": "null"
                            }
                        ]
                    }
                }
            }
        }
    },
    "definitions": {
        "login": {
            "type": "string",
            "minLength": 1
        },
        "nested": {
            "allOf": [
                {
                    "$ref": "#/definitions/login"
                }
            ]
        }
    }
}

