                    },
                    "BOTTOM": {
                        "default": "",
                        "id": "-b",
                        "type": "string"
                    },
                    "DEBUG": {
                        "default": false,
                        "id": "-d",
                        "type": "boolean"
                    },
                    "SEG": {
                        "default": false,
                        "id": "-2",
                        "type": "boolean"
                    },
                    "S_FAST": {
                        "default": "",
                        "id": "-S",
                        "type": "string"
                    },
                    "T2": {
                        "default": false,
                        "id": "-t2",
                        "type": "boolean"
                    },
                    "TOP": {
                        "default": "",
                        "id": "-t",
                        "type": "string"
                    },
                    "REGIONAL": {
                        "default": false,
                        "id": "-r",
                        "type": "boolean"
                    }
                },
                "required": [
                    "BET",
                    "BOTTOM",
                    "DEBUG",
                    "SEG",
                    "S_FAST",
                    "T2",
                    "TOP",
                    "REGIONAL"
                ]
            },
            "inputs": {
                "type": "object",
                "properties": {
                    "key": {
                        "type": "object"
                    },
                    "NIFTI": {
                        "type": "object",
                        "properties": {
                            "type": {
                                "enum": [
                                    "nifti"
                                ]
                            }
                        }
                    },
                    "lesion_mask": {
                        "type": "object",
                        "properties": {
                            "type": {
                                "enum": [
                                    "nifti"
                                ]
                            }
                        }
                    }
                },
                "required": [
                    "key",
                    "NIFTI"
                ]
            }
        },
        "required": [
            "config",
            "inputs"
        ]
    }
